-- UT Software — Tyre entry enum-assignment fix preflight
-- STRICTLY READ ONLY: catalog inspection and SELECT queries only.

with target as (
  select to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)') oid
), definition as (
  select oid,coalesce(pg_get_functiondef(oid),'') body from target
), enum_columns as (
  select table_name,column_name,udt_schema,udt_name from information_schema.columns
  where table_schema='public' and ((table_name='tyre_assets' and column_name='current_status') or (table_name='tyre_fitments' and column_name='resulting_status') or (table_name='tyre_asset_events' and column_name='event_type') or (table_name='tyre_vehicle_entries' and column_name in('source_type','work_type')) or (table_name='tyre_vehicle_entry_items' and column_name='work_type'))
), checks(check_name,status,details,blocking) as (
 values
 ('TARGET_RPC_EXISTS',case when (select oid from target) is not null then 'PASS' else 'FAIL' end,'Expected deployed save_vehicle_tyre_entry identity must exist.',true),
 ('ENUM_TYPES_EXIST',case when to_regtype('public.tyre_source_type') is not null and to_regtype('public.tyre_work_type') is not null and to_regtype('public.tyre_asset_status') is not null and to_regtype('public.tyre_event_type') is not null then 'PASS' else 'FAIL' end,'Required Tyre enum types must exist.',true),
 ('ENUM_COLUMN_TYPES',case when (select count(*) from enum_columns where udt_schema='public' and ((table_name='tyre_assets' and column_name='current_status' and udt_name='tyre_asset_status') or (table_name='tyre_fitments' and column_name='resulting_status' and udt_name='tyre_asset_status') or (table_name='tyre_asset_events' and column_name='event_type' and udt_name='tyre_event_type') or (table_name='tyre_vehicle_entries' and column_name='source_type' and udt_name='tyre_source_type') or (table_name='tyre_vehicle_entries' and column_name='work_type' and udt_name='tyre_work_type') or (table_name='tyre_vehicle_entry_items' and column_name='work_type' and udt_name='tyre_work_type')))=6 then 'PASS' else 'FAIL' end,coalesce((select string_agg(format('%s.%s=%s.%s',table_name,column_name,udt_schema,udt_name),'; ' order by table_name,column_name) from enum_columns),'Required enum columns are missing.'),true),
 ('KNOWN_CURRENT_STATUS_DEFECT',case when lower((select body from definition)) ~ 'current_status\s*=\s*case' and lower((select body from definition)) !~ '''fitted_again''::(public\.)?tyre_asset_status' then 'PASS' else 'FAIL' end,'Expected pending state: current_status CASE returns text without an explicit tyre_asset_status cast.',true),
 ('KNOWN_EVENT_TYPE_DEFECTS',case when lower((select body from definition)) ~ 'case\s+when\s+\(?v_asset_status\s*=' and lower((select body from definition)) ~ 'case\s+when\s+\(?v_work\s*=' and lower((select body from definition)) !~ '''fitted_again''::(public\.)?tyre_event_type' and lower((select body from definition)) !~ '''retread''::(public\.)?tyre_event_type' then 'PASS' else 'FAIL' end,'Both event_type CASE expressions are expected to return text in the known deployed body.',true),
 ('TYPED_ASSIGNMENTS_PRESERVED',case when lower((select body from definition)) ~ 'v_work\s+(public\.)?tyre_work_type' and lower((select body from definition)) ~ 'v_asset_status\s+(public\.)?tyre_asset_status' and lower((select body from definition)) ~ 'v_old_status\s+(public\.)?tyre_asset_status' then 'PASS' else 'FAIL' end,'Existing typed variables must remain enum-typed.',true),
 ('RPC_SECURITY',case when exists(select 1 from pg_proc p join target t on t.oid=p.oid where p.prosecdef and coalesce(array_to_string(p.proconfig,','),'') like '%search_path=public, pg_temp%') then 'PASS' else 'FAIL' end,'RPC must remain SECURITY DEFINER with locked search_path.',true),
 ('RPC_GRANTS',case when has_function_privilege('authenticated',(select oid from target),'EXECUTE') and not has_function_privilege('anon',(select oid from target),'EXECUTE') then 'PASS' else 'FAIL' end,'Authenticated execute required; anon prohibited.',true),
 ('ASSET_CURRENT_STATE_INTEGRITY',case when not exists(select 1 from public.tyre_assets where (current_status in('fitted','fitted_again') and (current_vehicle_id is null or current_position_id is null)) or (current_status not in('fitted','fitted_again') and (current_vehicle_id is not null or current_position_id is not null))) then 'PASS' else 'FAIL' end,(select format('%s asset row(s) violate current status/location integrity.',count(*)) from public.tyre_assets where (current_status in('fitted','fitted_again') and (current_vehicle_id is null or current_position_id is null)) or (current_status not in('fitted','fitted_again') and (current_vehicle_id is not null or current_position_id is not null))),true),
 ('ONE_OPEN_FITMENT_PER_ASSET',case when not exists(select 1 from public.tyre_fitments where removed_date is null group by tyre_asset_id having count(*)>1) then 'PASS' else 'FAIL' end,'No Tyre asset may have multiple open fitments.',true),
 ('ONE_OPEN_FITMENT_PER_POSITION',case when not exists(select 1 from public.tyre_fitments where removed_date is null group by vehicle_position_id having count(*)>1) then 'PASS' else 'FAIL' end,'No Vehicle position may have multiple open fitments.',true),
 ('OPEN_FITMENT_ASSET_MATCH',case when not exists(select 1 from public.tyre_fitments f join public.tyre_assets a on a.id=f.tyre_asset_id where f.removed_date is null and (a.current_status not in('fitted','fitted_again') or a.current_vehicle_id is distinct from f.vehicle_id or a.current_position_id is distinct from f.vehicle_position_id)) then 'PASS' else 'FAIL' end,'Every open fitment must match asset current state.',true),
 ('NO_ORPHAN_TYRE_RELATIONS',case when not exists(select 1 from public.tyre_vehicle_entry_items i left join public.tyre_vehicle_entries e on e.id=i.tyre_vehicle_entry_id where e.id is null) and not exists(select 1 from public.tyre_fitments f left join public.tyre_assets a on a.id=f.tyre_asset_id left join public.tyre_vehicle_entries e on e.id=f.source_entry_id where a.id is null or e.id is null) and not exists(select 1 from public.tyre_asset_events e left join public.tyre_assets a on a.id=e.tyre_asset_id where a.id is null) then 'PASS' else 'FAIL' end,'No orphan Entry Item, Fitment or Asset Event rows.',true),
 ('NO_CONFLICTING_LATER_FIX',case when lower((select body from definition)) !~ '''fitted_again''::(public\.)?tyre_asset_status' then 'PASS' else 'FAIL' end,'A corrected/conflicting later body must not already be deployed.',true),
 ('MIGRATION_HISTORY_STATE',case when to_regclass('supabase_migrations.schema_migrations') is null then 'INFO' when exists(select 1 from supabase_migrations.schema_migrations where version='202608290001') then 'FAIL' else 'PASS' end,case when to_regclass('supabase_migrations.schema_migrations') is null then 'Migration history is not visible.' when exists(select 1 from supabase_migrations.schema_migrations where version='202608290001') then 'Version 202608290001 is already recorded; do not rerun.' else 'Version 202608290001 is pending.' end,true),
 ('TYRE_DATA_SNAPSHOT','INFO',format('assets=%s; entries=%s; items=%s; fitments=%s; events=%s',(select count(*) from public.tyre_assets),(select count(*) from public.tyre_vehicle_entries),(select count(*) from public.tyre_vehicle_entry_items),(select count(*) from public.tyre_fitments),(select count(*) from public.tyre_asset_events)),false),
 ('ACCOUNTING_BOUNDARY','INFO','The fix replaces one RPC only; no Cashbook, Voucher, supplier, profitability or business-data DML.',false)
), combined as (
 select 'OVERALL_TYRE_ENTRY_ENUM_FIX_PREFLIGHT'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_TYRE_ENTRY_ENUM_FIX_PREFLIGHT' then 0 else 1 end,check_name;
